import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Services = () => {
  const [services, setServices] = useState([]);

  useEffect(() => {
    fetchServices();
  }, []);

  const fetchServices = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/services');
      setServices(response.data);
    } catch (error) {
      console.error('Error fetching services:', error);
    }
  };

  const defaultServices = [
    { name: 'AC Motor Winding', category: 'motor-winding', description: 'Complete AC motor rewinding service', price: 2500 },
    { name: 'DC Motor Repair', category: 'motor-repair', description: 'DC motor maintenance and repair', price: 1800 },
    { name: 'Generator Service', category: 'generator-repair', description: 'Generator maintenance and repair', price: 3500 }
  ];

  const displayServices = services.length > 0 ? services : defaultServices;

  return (
    <div className="container" style={{ padding: '40px 20px' }}>
      <h1>Our Services</h1>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px', marginTop: '30px' }}>
        {displayServices.map((service, index) => (
          <div key={index} style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px' }}>
            <h3>{service.name}</h3>
            <p style={{ margin: '10px 0' }}>{service.description}</p>
            <p style={{ fontWeight: 'bold', color: '#007bff' }}>₹{service.price}</p>
            <span style={{ 
              background: '#f8f9fa', 
              padding: '4px 8px', 
              borderRadius: '4px', 
              fontSize: '12px',
              textTransform: 'capitalize'
            }}>
              {service.category?.replace('-', ' ')}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Services;
